#!/usr/bin/env python3
"""DAY330 [TERCEROS-ZEEK-D330] DEBT-LAB-VERSIONES-TERCEROS-001, lente Zeek (decisión de Alonso DAY330: opción (a), la serie).

Nuevos: provisioning/zeek/VERSION (serie 9.0), provisioning/zeek/CLAVE (huella de OBS, medida DAY330),
scripts/vigilancia/zeek_instalar.sh (repo_oficial + paquete de la serie + comprobación + apt-mark hold) y
scripts/vigilancia/test_zeek_instalar.sh. Vagrantfile: install-zeek llama a zeek_instalar.sh (fuera el curl sin comprobar
y el zeek sin fijar). Makefile: target test-zeek-instalar y su paso en EMECAS, tras test-falco-silencio.

Uso (Mac, raíz del repo): python3 -I scripts/etcd_ha/d330_terceros_zeek.py [--apply]
Sin --apply solo comprueba. Con --apply escribe, y solo si TODO cuadra: sha256 de partida de cada fichero que modifica,
cada ancla exactamente las veces esperadas y ningún fichero nuevo ya existente. Si algo falla no escribe nada.
"""
import hashlib, os, sys

NUEVOS = {'provisioning/zeek/VERSION': ('9.0\n', 420), 'provisioning/zeek/CLAVE': ('# provisioning/zeek/CLAVE — [TERCEROS-ZEEK-D330] huella de la clave con la que OBS firma el repositorio de Zeek\n# (https://download.opensuse.org/repositories/security:/zeek/Debian_12/Release.key,\n# "security OBS Project <security@build.opensuse.org>": es la clave del proyecto security de OBS entero, no solo de Zeek).\n# scripts/vigilancia/lib_apt_oficial.sh descarga la clave y SOLO la instala si todas sus claves principales están aquí.\n# Medida DAY330 en la clave que el lab tenía instalada (creada el 23-sep-2024; caduca el 2-dic-2026 12:27 UTC: OBS suele\n# prorrogarla con la MISMA huella, y entonces aquí no cambia nada; una VM aprovisionada antes de la prórroga deja de\n# poder hacer apt update contra Zeek hasta que se vuelve a aprovisionar). No la publica nadie más (búsqueda DAY330):\n# contrastarla con OBS/Zeek, DEBT-SUPPLY-CHAIN-ORIGEN-OFICIAL-001. Si OBS rota la clave, se añade la nueva aquí (una\n# por línea) tras contrastarla.\nF9FA0223B56B116C363737EF5DA57BDD6DD785CA\n', 420), 'scripts/vigilancia/zeek_instalar.sh': ('#!/usr/bin/env bash\n# scripts/vigilancia/zeek_instalar.sh — [TERCEROS-ZEEK-D330] DEBT-LAB-VERSIONES-TERCEROS-001, lente Zeek: Zeek desde el\n# repositorio de OBS (el de los binarios de Zeek), con su clave comprobada por huella y la SERIE fijada.\n# Se ejecuta EN la VM zeek, como root: aprovisionador install-zeek del Vagrantfile. Lee de provisioning/zeek/:\n#   VERSION  la serie de Zeek, M.m (p. ej. 9.0). Formato exacto: dígitos, punto, dígitos. Sin defecto: mal o ausente,\n#            para (es un error de fabricante: el lab lo ve antes que nadie).\n#   CLAVE    huella de la clave de firma de OBS (lib_apt_oficial.sh)\n# Por qué la serie y no la versión exacta (medido DAY330): OBS solo guarda la última versión de cada paquete\n# (apt-cache madison da una), así que fijar zeek=9.0.1-0 rompería el lab el día que publiquen la 9.0.2. Se instala el\n# paquete de la serie, zeek-M.m (sus dependencias van con "=" a su misma versión), se comprueba que todo lo de Zeek\n# instalado es de esa serie y de esa versión, que el binario dice esa versión, y se fija todo con apt-mark hold. Un\n# cambio de serie solo entra con un commit en VERSION. Los paquetes de serie y los sin serie (zeek, zeek-core...) NO se\n# declaran en conflicto pero comparten /opt/zeek (medido DAY330): si ya hay de Zeek fuera de la serie, para sin tocar nada.\n# Las funciones zeek_* no tocan el sistema (las prueba scripts/vigilancia/test_zeek_instalar.sh en el Mac).\nset -u\nLC_ALL=C; export LC_ALL\nlog() { echo "[TERCEROS-ZEEK] $*"; }\nfallo() { echo "[TERCEROS-ZEEK] FALLA: $*"; exit 1; }\n\n# zeek_serie_valida SERIE -> rc 0 si es M.m\nzeek_serie_valida() {\n  printf \'%s\\n\' "$1" | grep -Eqx \'[0-9]{1,3}[.][0-9]{1,3}\'\n}\n\n# zeek_en_serie SERIE PAQUETE -> rc 0 si el paquete es de la serie (zeek-S, zeek-S-*, zeekctl-S, zeekctl-S-*)\nzeek_en_serie() {\n  case "$2" in\n    "zeek-$1"|"zeek-$1-"*|"zeekctl-$1"|"zeekctl-$1-"*) return 0 ;;\n  esac\n  return 1\n}\n\n# zeek_fuera_de_serie SERIE < paquetes (uno por línea) -> imprime los que no son de la serie\nzeek_fuera_de_serie() {\n  local p\n  while IFS= read -r p; do\n    [ -n "$p" ] || continue\n    zeek_en_serie "$1" "$p" || printf \'%s\\n\' "$p"\n  done\n  return 0\n}\n\n# zeek_comprobar SERIE VERSION_DEL_PAQUETE_DE_SERIE SALIDA_DE_zeek_--version < "paquete=versión" (uno por línea)\n#   -> rc 0 si: la versión es de la serie; están zeek-S y zeek-S-core; todo es de la serie y de esa versión; y el binario\n#      dice esa versión (sin la revisión de Debian). Si no, una línea por fallo y rc 1.\nzeek_comprobar() {\n  local s=$1 v=$2 bin=$3 linea p pv mal=0 meta=0 core=0\n  case "$v" in\n    "$s".*) ;;\n    *) echo "zeek-$s en \'$v\', fuera de la serie $s"; mal=1 ;;\n  esac\n  while IFS= read -r linea; do\n    [ -n "$linea" ] || continue\n    p=${linea%%=*}; pv=${linea#*=}\n    [ "$p" = "zeek-$s" ] && meta=1\n    [ "$p" = "zeek-$s-core" ] && core=1\n    if ! zeek_en_serie "$s" "$p"; then echo "$p ($pv) no es de la serie $s"; mal=1\n    elif [ "$pv" != "$v" ]; then echo "$p en $pv, no en $v (la de zeek-$s)"; mal=1\n    fi\n  done\n  [ "$meta" = 1 ] || { echo "falta zeek-$s"; mal=1; }\n  [ "$core" = 1 ] || { echo "falta zeek-$s-core"; mal=1; }\n  [ "$bin" = "/opt/zeek/bin/zeek version ${v%-*}" ] || { echo "el binario dice \'$bin\', se espera la versión ${v%-*}"; mal=1; }\n  return "$mal"\n}\n\nzeek_instalados() {\n  dpkg-query -W -f=\'${Package}=${Version}=${Status}\\n\' \'zeek*\' 2>/dev/null | awk -F= \'$3 ~ / installed$/ {print $1 "=" $2}\'\n}\n\nmain() {\n  local src=${ZEEK_SRC:-/vagrant/provisioning/zeek} lib s fuera actuales v bin informe\n  lib=$(dirname "${BASH_SOURCE[0]}")/lib_apt_oficial.sh\n  [ "$(id -u)" = 0 ] || fallo "hay que ejecutarlo como root"\n  for f in VERSION CLAVE; do [ -r "$src/$f" ] || fallo "no leo $src/$f"; done\n  s=$(tr -d \'[:space:]\' < "$src/VERSION")\n  zeek_serie_valida "$s" || fallo "$src/VERSION: \'$s\' mal formado (la serie, M.m: p. ej. 9.0). ERROR DE FABRICANTE: avisar a aRGus"\n  log "serie $s (de $src/VERSION)"\n  fuera=$(zeek_instalados | cut -d= -f1 | zeek_fuera_de_serie "$s")\n  [ -z "$fuera" ] || fallo "ya hay paquetes de Zeek fuera de la serie $s: $(echo $fuera) (comparten /opt/zeek; no se tocan: vagrant destroy zeek y volver a subirla)"\n  # shellcheck source=lib_apt_oficial.sh\n  . "$lib"\n  repo_oficial zeek https://download.opensuse.org/repositories/security:/zeek/Debian_12/Release.key "$src/CLAVE" \\\n    http://download.opensuse.org/repositories/security:/zeek/Debian_12/ "/" || fallo "repositorio de Zeek"\n  apt-get update -qq || fallo "apt-get update"\n  actuales=$(zeek_instalados | cut -d= -f1)\n  [ -z "$actuales" ] || apt-mark unhold $actuales >/dev/null\n  DEBIAN_FRONTEND=noninteractive apt-get install -y "zeek-$s" || fallo "apt-get install zeek-$s"\n  v=$(dpkg-query -W -f=\'${Version}\' "zeek-$s" 2>/dev/null)\n  bin=$(/opt/zeek/bin/zeek --version 2>&1)\n  informe=$(zeek_instalados | zeek_comprobar "$s" "$v" "$bin") || fallo "lo instalado no cuadra con la serie $s: $(echo $informe)"\n  apt-mark hold $(zeek_instalados | cut -d= -f1) >/dev/null || fallo "apt-mark hold"\n  log "✅ zeek $v (serie $s de provisioning/zeek/VERSION), $(zeek_instalados | wc -l | tr -d \' \') paquetes fijados (apt-mark hold): $(echo $(zeek_instalados))"\n}\n\nif [ "${BASH_SOURCE[0]}" = "$0" ]; then main "$@"; fi\n', 420), 'scripts/vigilancia/test_zeek_instalar.sh': ('#!/usr/bin/env bash\n# scripts/vigilancia/test_zeek_instalar.sh — [TERCEROS-ZEEK-D330] tests de las funciones zeek_* de zeek_instalar.sh\n# (Mac, sin VMs: no tocan el sistema). Cada caso de rechazo se vuelve a correr contra un comprobador que lo acepta todo,\n# y tiene que fallar ahí: así se ve que el test distingue (que no da verde en falso).\nset -u\nLC_ALL=C; export LC_ALL\n. "$(dirname "$0")/zeek_instalar.sh"\n\nBIEN=$\'zeek-9.0=9.0.1-0\\nzeek-9.0-core=9.0.1-0\\nzeek-9.0-core-dev=9.0.1-0\\nzeek-9.0-spicy-dev=9.0.1-0\\nzeek-9.0-zkg=9.0.1-0\\nzeek-9.0-client=9.0.1-0\\nzeekctl-9.0=9.0.1-0\'\nBIN=\'/opt/zeek/bin/zeek version 9.0.1\'\ncasos=0; fallos=0; rechazos=0; rechazos_vistos=0\n\n# acepta NOMBRE ORDEN...  /  rechaza NOMBRE ORDEN...\nacepta() { local n=$1; shift; casos=$((casos + 1)); if "$@" >/dev/null 2>&1; then echo "✅ $n"; else echo "❌ $n"; fallos=$((fallos + 1)); fi; }\nrechaza() { local n=$1; shift; casos=$((casos + 1)); rechazos=$((rechazos + 1)); if "$@" >/dev/null 2>&1; then echo "❌ $n"; fallos=$((fallos + 1)); rechazos_vistos=$((rechazos_vistos + 1)); else echo "✅ $n"; fi; }\nfuera_vacio() { [ -z "$(printf \'%s\\n\' "$2" | zeek_fuera_de_serie "$1")" ]; }\nfuera_es() { [ "$(printf \'%s\\n\' "$2" | zeek_fuera_de_serie "$1")" = "$3" ]; }\ncomprueba() { printf \'%s\\n\' "$4" | zeek_comprobar "$1" "$2" "$3"; }\n\nlos_casos() {\n  acepta "serie 9.0 válida" zeek_serie_valida 9.0\n  acepta "serie 10.12 válida" zeek_serie_valida 10.12\n  rechaza "serie 9 (sin menor)" zeek_serie_valida 9\n  rechaza "serie 9.0.1 (versión exacta, no serie)" zeek_serie_valida 9.0.1\n  rechaza "serie vacía" zeek_serie_valida ""\n  rechaza "serie 9.x" zeek_serie_valida 9.x\n  rechaza "serie lts (por nombre)" zeek_serie_valida lts\n  acepta "todo de la serie 9.0: nada fuera" fuera_vacio 9.0 $\'zeek-9.0\\nzeek-9.0-core\\nzeekctl-9.0\'\n  acepta "lista vacía: nada fuera" fuera_vacio 9.0 ""\n  rechaza "zeek y zeek-core (sin serie) están fuera" fuera_vacio 9.0 $\'zeek\\nzeek-core\\nzeek-9.0\'\n  acepta "fuera: exactamente los sin serie" fuera_es 9.0 $\'zeek\\nzeek-9.0\\nzeek-core\' $\'zeek\\nzeek-core\'\n  rechaza "zeek-9.01-core no es de la serie 9.0" fuera_vacio 9.0 "zeek-9.01-core"\n  rechaza "zeek-90-core no es de la serie 9.0 (el punto es literal)" fuera_vacio 9.0 "zeek-90-core"\n  rechaza "zeek-8.0 no es de la serie 9.0" fuera_vacio 9.0 "zeek-8.0"\n  acepta "lo instalado medido DAY330 en la serie 9.0" comprueba 9.0 9.0.1-0 "$BIN" "$BIEN"\n  rechaza "un paquete en otra versión" comprueba 9.0 9.0.1-0 "$BIN" "${BIEN/zeek-9.0-zkg=9.0.1-0/zeek-9.0-zkg=9.0.0-0}"\n  rechaza "versión del paquete de serie fuera de la serie" comprueba 9.0 9.1.0-0 \'/opt/zeek/bin/zeek version 9.1.0\' "${BIEN//9.0.1-0/9.1.0-0}"\n  rechaza "el binario dice otra versión" comprueba 9.0 9.0.1-0 \'/opt/zeek/bin/zeek version 8.0.4\' "$BIEN"\n  rechaza "el binario no responde" comprueba 9.0 9.0.1-0 \'\' "$BIEN"\n  rechaza "falta zeek-9.0-core" comprueba 9.0 9.0.1-0 "$BIN" "${BIEN/zeek-9.0-core=9.0.1-0/}"\n  rechaza "falta el metapaquete zeek-9.0" comprueba 9.0 9.0.1-0 "$BIN" "${BIEN/zeek-9.0=9.0.1-0/}"\n  rechaza "un paquete sin serie entre lo instalado" comprueba 9.0 9.0.1-0 "$BIN" "$BIEN"$\'\\nzeek-core=9.0.1-0\'\n  rechaza "nada instalado" comprueba 9.0 9.0.1-0 "$BIN" ""\n}\n\nlos_casos\necho "$((casos - fallos))/$casos casos"\ntotal=$fallos\n\n# Contra un comprobador que lo acepta todo, cada rechazo tiene que dar ❌.\nzeek_serie_valida() { return 0; }\nzeek_en_serie() { return 0; }\nzeek_comprobar() { cat >/dev/null; return 0; }\nesperados=$rechazos; casos=0; fallos=0; rechazos=0; rechazos_vistos=0\nlos_casos > /dev/null\nif [ "$rechazos_vistos" = "$esperados" ]; then\n  echo "✅ contra un comprobador que lo acepta todo fallan los $esperados casos de rechazo"\nelse\n  echo "❌ contra un comprobador que lo acepta todo fallan $rechazos_vistos de los $esperados casos de rechazo"; total=$((total + 1))\nfi\n[ "$total" = 0 ]\n', 420)}

MODIFICA = {'Vagrantfile': ('d6202d320b009632af1a52bad384e7b4c0a9a3ee450dac870d292e10e0e961b4', [('      # Zeek repo oficial OpenSUSE\n      echo \'deb http://download.opensuse.org/repositories/security:/zeek/Debian_12/ /\' \\\n        > /etc/apt/sources.list.d/zeek.list\n      curl -fsSL https://download.opensuse.org/repositories/security:/zeek/Debian_12/Release.key \\\n        | gpg --dearmor > /etc/apt/trusted.gpg.d/zeek.gpg\n      apt-get update -qq\n      apt-get install -y zeek || { echo "❌ zeek install failed"; exit 1; }\n', '      # [TERCEROS-ZEEK-D330] DEBT-LAB-VERSIONES-TERCEROS-001, lente Zeek: el repositorio de OBS con su clave comprobada por\n      # huella (provisioning/zeek/CLAVE) y la serie fija de provisioning/zeek/VERSION; todo en zeek_instalar.sh (su\n      # cabecera explica por qué la serie y no la versión exacta). Antes: el paquete zeek sin fijar (la última serie del\n      # día) y la clave bajada sin comprobar.\n      bash /vagrant/scripts/vigilancia/zeek_instalar.sh || { echo "❌ zeek install failed"; exit 1; }\n', 1)]), 'Makefile': ('34cf9516f64b5be9be67bb6ee9635a090030de7d328d011c5e5b74b37bd0b3ed', [('test-falco-silencio:\n\t@python3 -I scripts/vigilancia/test_falco_silencio.py\n', 'test-falco-silencio:\n\t@python3 -I scripts/vigilancia/test_falco_silencio.py\n\n# [TERCEROS-ZEEK-D330] test-zeek-instalar (Mac, sin VMs): las funciones de scripts/vigilancia/zeek_instalar.sh (serie\n# de provisioning/zeek/VERSION y la comprobación de lo instalado), también contra un comprobador que lo acepta todo.\n.PHONY: test-zeek-instalar\ntest-zeek-instalar:\n\t@bash scripts/vigilancia/test_zeek_instalar.sh\n', 1), ('\t@$(EMECAS_PASO) test-falco-silencio -- $(MAKE) test-falco-silencio\n', '\t@$(EMECAS_PASO) test-falco-silencio -- $(MAKE) test-falco-silencio\n\t@$(EMECAS_PASO) test-zeek-instalar -- $(MAKE) test-zeek-instalar\n', 1)])}

def main():
    aplicar = "--apply" in sys.argv[1:]
    if not os.path.isfile("Vagrantfile") or not os.path.isfile("Makefile"):
        sys.exit("❌ ejecutar desde la raíz del repo")
    errores, resultado = [], {}
    for ruta in NUEVOS:
        if os.path.exists(ruta):
            errores.append("ya existe " + ruta)
    for ruta, (sha_partida, cambios) in MODIFICA.items():
        datos = open(ruta, "rb").read()
        h = hashlib.sha256(datos).hexdigest()
        if h != sha_partida:
            errores.append("%s: sha256 de partida %s, esperado %s" % (ruta, h, sha_partida))
            continue
        texto = datos.decode("utf-8")
        for viejo, nuevo, veces in cambios:
            n = texto.count(viejo)
            if n != veces:
                errores.append("%s: ancla %d veces, esperadas %d: %r" % (ruta, n, veces, viejo[:90]))
            else:
                texto = texto.replace(viejo, nuevo)
        resultado[ruta] = texto
    if errores:
        print("❌ no se escribe nada:")
        for e in errores:
            print("   - " + e)
        sys.exit(1)
    if not aplicar:
        print("✅ todo cuadra (sin --apply no se escribe nada): %d nuevos, %d modificados" % (len(NUEVOS), len(resultado)))
        return
    for ruta, (contenido, modo) in NUEVOS.items():
        os.makedirs(os.path.dirname(ruta) or ".", exist_ok=True)
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(contenido)
        os.chmod(ruta, modo)
        print("  + %s  sha256=%s" % (ruta, hashlib.sha256(contenido.encode()).hexdigest()))
    for ruta, texto in resultado.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("  ~ %s  sha256=%s" % (ruta, hashlib.sha256(texto.encode()).hexdigest()))
    print("✅ aplicado")

if __name__ == "__main__":
    main()
